import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) throws IOException {
        Scanner in = new Scanner(System.in);
        int n = Integer.parseInt(in.nextLine().trim());
        List<String> daftar = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            daftar.add(in.nextLine().trim());
        }
        String susulan = in.nextLine().trim();

        Path path = Path.of("katalog.csv");
        List<String> isi = new ArrayList<>();
        // 1) Tulis ke katalog.csv: baris judul kolom "kode,judul", lalu semua isi daftar, satu per baris (timpa berkas lama). 2) Baca kembali isinya, tambahkan baris susulan ke daftar hasil baca itu, lalu tulis ulang seluruh berkas. 3) Baca semua baris berkas ke daftar isi (Files.readAllLines).

        System.out.println("Banyak judul: " + (isi.size() - 1));
        for (int i = 1; i < isi.size(); i++) {
            System.out.println("- " + isi.get(i).split(",")[1]);
        }
        Files.deleteIfExists(path);
    }
}
